<div class="gestion-dos-columnas"><section class="gestion-tarjeta"><h2><?= $m ? 'Editar profesional' : 'Registrar profesional' ?></h2><form method="post" class="form-gestion" data-csrf><?php campo_csrf(); ?><input type="hidden" name="accion" value="medico"><input type="hidden" name="medico_id" value="<?= (int)($m['id'] ?? 0) ?>"><label>Nombres y apellidos<input name="nombres" minlength="5" maxlength="120" value="<?= e($m['nombres'] ?? '') ?>" required></label><label>Código o colegiatura<input name="colegiatura" pattern="[A-Za-z0-9-]{3,20}" maxlength="20" value="<?= e($m['colegiatura'] ?? '') ?>" required></label><label>Especialidad<?php campo_buscador('especialidad', 'especialidad_id', $m['especialidad_id'] ?? 0, ['alcance' => 'todos', 'requerido' => true, 'etiqueta' => 'Especialidad', 'placeholder' => 'Buscar especialidad']); ?></label><label>Consultorio para nuevas reservas<select name="consultorio_id" data-buscador-local><option value="">Conservar asignación</option><?php foreach($conexion->query('SELECT * FROM consultorios WHERE activo=1 ORDER BY nombre') as $sala):?><option value="<?= $sala['id'] ?>" <?= (int)($m['consultorio_id']??0)===(int)$sala['id']?'selected':'' ?>><?= e($sala['nombre']) ?></option><?php endforeach ?></select></label><label>Presentación<textarea name="descripcion" maxlength="500"><?= e($m['descripcion'] ?? '') ?></textarea></label><label class="checkbox-inline"><input type="checkbox" name="activo" <?= !$m || $m['activo'] ? 'checked' : '' ?>> Disponible para nuevas reservas</label><button class="boton boton-primario">Guardar profesional</button><?php if ($m): ?><a href="admin_medicos.php">Registrar otro profesional</a><?php endif ?></form></section>
<section class="gestion-tarjeta"><h2>Equipo registrado</h2>
<form method="get" class="gestion-filtros"><label>Profesional<?php campo_buscador('medico', 'id', $mid, ['alcance' => 'todos', 'requerido' => true, 'etiqueta' => 'Profesional', 'placeholder' => 'Buscar en todo el equipo']); ?></label><button class="boton boton-primario">Ver profesional</button></form><p class="texto-ayuda">La disponibilidad para nuevas reservas se administra por separado de los compromisos ya registrados.</p><div class="medicos-admin-lista"><?php foreach ($conexion->query('SELECT m.*,e.nombre especialidad FROM medicos m JOIN especialidades e ON e.id=m.especialidad_id ORDER BY m.nombres,m.id LIMIT 20') as $prof): ?><a href="?id=<?= (int)$prof['id'] ?>" class="medico-admin"><span class="avatar-medico"><?= e(mb_substr($prof['nombres'], 0, 1)) ?></span><span><strong><?= e($prof['nombres']) ?></strong><small><?= e($prof['especialidad']) ?> · <?= $prof['activo'] ? 'Activo' : 'Inactivo' ?></small></span><i class="fas fa-chevron-right" aria-hidden="true"></i></a><?php endforeach ?></div></section></div>
<?php if ($m): ?>
<p><a class="boton boton-secundario" href="reorganizar.php?medico=<?= $mid ?>">Reorganizar citas del profesional</a></p><section class="gestion-tarjeta"><h2>Turnos de <?= e($m['nombres']) ?></h2><p class="texto-ayuda">Cada turno genera espacios de atención según su duración. Solo se puede retirar un turno sin citas futuras. Para ausencias utiliza Reorganizar citas y coordina las propuestas antes de modificar los turnos.</p>
<form method="post" class="gestion-filtros" data-csrf><?php campo_csrf(); ?><input type="hidden" name="accion" value="turno"><input type="hidden" name="medico_id" value="<?= $mid ?>"><label>Día<select name="dia"><?php foreach ($dias as $v => $t): ?><option value="<?= $v ?>"><?= $t ?></option><?php endforeach ?></select></label><label>Desde<input type="time" name="inicio" required></label><label>Hasta<input type="time" name="fin" required></label><label>Duración<select name="duracion"><?php foreach ([15,30,45,60] as $v): ?><option value="<?= $v ?>" <?= $v === 30 ? 'selected' : '' ?>><?= $v ?> minutos</option><?php endforeach ?></select></label><label>Vigente desde<input type="date" name="vigencia" min="<?= date('Y-m-d') ?>" value="<?= date('Y-m-d') ?>" required></label><button class="boton boton-primario">Agregar turno</button></form>
<div class="tabla-desplazable" tabindex="0" role="region" aria-label="Turnos"><table class="table tabla-gestion"><thead><tr><th scope="col">Día</th><th scope="col">Horario</th><th scope="col">Duración</th><th scope="col">Acción</th></tr></thead><tbody><?php $s = $conexion->prepare('SELECT * FROM turnos WHERE medico_id=? ORDER BY dia,inicio');
    $s->execute([$mid]);
    foreach ($s->fetchAll() as $t): ?><tr><td><?= $dias[$t['dia']] ?></td><td><?= e(substr($t['inicio'], 0, 5)) ?> a <?= e(substr($t['fin'], 0, 5)) ?></td><td><?= (int)$t['duracion'] ?> minutos</td><td><form method="post" data-confirmar="¿Quitar este turno? Las citas anteriores se conservarán."><?php campo_csrf(); ?><input type="hidden" name="accion" value="quitar_turno"><input type="hidden" name="medico_id" value="<?= $mid ?>"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><label>Retirar desde<input type="date" name="vigencia" min="<?= date('Y-m-d') ?>" value="<?= date('Y-m-d') ?>" required></label><button class="boton boton-secundario">Quitar turno</button></form></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="gestion-tarjeta"><h2>Bloquear una fecha u horario</h2><p class="texto-ayuda">Para bloquear el día completo utiliza 00:00 a 23:59. No se admite bloquear turnos con citas pendientes o confirmadas.</p>
<form method="post" class="gestion-filtros" data-csrf><?php campo_csrf(); ?><input type="hidden" name="accion" value="bloqueo"><input type="hidden" name="medico_id" value="<?= $mid ?>"><label>Fecha<input type="date" name="fecha" min="<?= date('Y-m-d') ?>" max="<?= date('Y-m-d', strtotime('+180 days')) ?>" required></label><label>Desde<input type="time" name="inicio" value="00:00" required></label><label>Hasta<input type="time" name="fin" value="23:59" required></label><label>Motivo<input name="motivo" minlength="5" maxlength="250" required></label><button class="boton boton-primario">Bloquear horario</button></form>
<?php $s = $conexion->prepare('SELECT * FROM bloqueos WHERE medico_id=? AND fecha>=CURDATE() ORDER BY fecha,inicio');
    $s->execute([$mid]);
    $bs = $s->fetchAll();
    if (!$bs): ?><p class="texto-ayuda">No hay bloqueos futuros.</p><?php endif ?><div class="bloqueos-lista"><?php foreach ($bs as $b): ?><div><p><strong><?= fecha_texto($b['fecha']) ?> · <?= e(substr($b['inicio'], 0, 5)) ?> a <?= e(substr($b['fin'], 0, 5)) ?></strong><span><?= e($b['motivo']) ?></span></p><form method="post" data-confirmar="¿Habilitar nuevamente este horario?"><?php campo_csrf(); ?><input type="hidden" name="accion" value="quitar_bloqueo"><input type="hidden" name="medico_id" value="<?= $mid ?>"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><button class="boton boton-secundario">Quitar bloqueo</button></form></div><?php endforeach ?></div></section>
<section class="gestion-tarjeta"><h2>Historial de horarios</h2><p>La tabla anterior muestra el último plan. La agenda utiliza la versión vigente para cada fecha; los días anteriores a la primera versión se muestran como estimación.</p><?php $q=$conexion->prepare('SELECT desde,creado_en FROM horarios_versiones WHERE medico_id=? ORDER BY desde DESC');$q->execute([$mid]);foreach($q as $v):?><p>Vigente desde <?= fecha_texto($v['desde']) ?> · registrado <?= e($v['creado_en']) ?></p><?php endforeach ?></section><?php endif;
cerrar_pagina(); ?>
